  PAPILDU.push(...[{"lv": "Kas notiek?", "ru": "Что происходит?", "en": "What is happening?"}, {"lv": "Vieta zināma", "ru": "Место известно", "en": "Place known"}, {"lv": "Adrese nav jāraksta vēlreiz.", "ru": "Адрес вводить заново не нужно.", "en": "No need to type the address again."}, {"lv": "Cits…", "ru": "Другое…", "en": "Other…"}, {"lv": "Aprakstiet, kas notiek", "ru": "Опишите, что происходит", "en": "Describe what is happening"}, {"lv": "Rādīt", "ru": "Показать", "en": "Show"}, {"lv": "Rīcības plāns", "ru": "План действий", "en": "Action plan"}, {"lv": "Situācija vēl nav izvēlēta; vispārīgs gatavības plāns:", "ru": "Ситуация ещё не выбрана; общий план готовности:", "en": "No situation chosen yet; general preparedness plan:"}]);
